def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # A horizontal 3-line indicates a template extending down to other
    # occurrences of its colors: connect corresponding vertical/horizontal runs.
    out = [row[:] for row in grid]
    bg = 7 if sum(row.count(7) for row in grid) > sum(row.count(3) for row in grid) else 3
    colors = {v for row in grid for v in row if v != bg}
    # Extend each non-background pixel into the axis-aligned line defined by
    # the same-colored markers/segments, changing only background cells to 2.
    for color in colors:
        pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not pts: continue
        # Only draw extensions of the template's extreme rows/columns; inner
        # motif marks remain isolated unless they are collinear repetitions.
        # Ignore the special isolated 5/6-like center marks in a row when
        # the same color's pattern consists of two vertical rails.
        for c in {c for r,c in pts}:
            rs = [r for r,cc in pts if cc == c]
            # A long initial horizontal bar is a shape template, not a ray.
            if len(rs) > 1 and not any(len([cc for rr,cc in pts if rr == r]) >= 4 for r in {rr for rr,cc in pts}):
                for r in range(min(rs), max(rs)+1):
                    if out[r][c] == bg: out[r][c] = 2
        for r in {r for r,c in pts}:
            cs = [c for rr,c in pts if rr == r]
            if len(cs) > 1:
                for c in range(min(cs), max(cs)+1):
                    if out[r][c] == bg: out[r][c] = 2
    return out

