def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Bridge gaps on the extreme axes of a right-angle scaffold. The most
    # frequent non-background alignment supplies the two rail columns.
    nonbg = [v for row in grid for v in row if v != bg]
    color = Counter(nonbg).most_common(1)[0][0]
    positions = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
    counts = Counter(c for r,c in positions)
    rails = [c for c,n in counts.items() if n >= 3]
    for c in rails:
        rows = [r for r,cc in positions if cc == c]
        for a,b in zip(rows, rows[1:]):
            for r in range(a+1,b):
                if grid[r][c] == bg: out[r][c]=2
    # horizontal gaps between successive cells on the scaffold's horizontal bars
    rowcounts = Counter(r for r,c in positions)
    for r,n in rowcounts.items():
        if n >= 2:
            cols = [c for rr,c in positions if rr == r]
            for a,b in zip(cols,cols[1:]):
                for c in range(a+1,b):
                    if grid[r][c] == bg: out[r][c]=2
    return out

