                (c == 0 or grid[r][c-1] == bg) and
                (c == w-1 or grid[r][c+1] == bg)]
        for a, b in zip(rows, rows[1:]):
            if 1 <= b-a-1 <= 4:
                for r in range(a+1, b):
                    if grid[r][c] == bg: out[r][c] = 2
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] != bg and
                (r == 0 or grid[r-1][c] == bg) and
                (r == h-1 or grid[r+1][c] == bg)]
        for a, b in zip(cols, cols[1:]):
            if 1 <= b-a-1 <= 4:
                for c in range(a+1, b):
                    if grid[r][c] == bg: out[r][c] = 2
    return out
